SELECT 'gongkao', '剩余工程反求', 'kp-eng-st-remain', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "剩余工程反求"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "未知总量，已知“完成部分后剩余的绝对时间”，列方程倒推。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "经典句式：“修一条路，甲修了 3 天，乙修了 5 天后，剩下的若由甲单独修还需要 4 天，若由乙单独修还需要 6 天……”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导：建立等效替换等式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "仔细读题，你会发现对“剩余工程”通常有两种不同的完成方式。这正是破题的黄金等式！"}]}, {"type": "katexBlock", "attrs": {"content": "\\text{剩余方式 1 所需的工作量} = \\text{剩余方式 2 所需的工作量}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[剥离出关于'剩余工程'的两套不同方案] --> B[列出等式: 方案1的效率×时间 = 方案2的效率×时间]\nB --> C[通过等式直接求出甲乙的【效率比】]\nC --> D[直接将效率比赋值为具体的 P甲 和 P乙]\nD --> E[代回题干的任何一套完整方案, 求出工程总量 W]\nE --> F[解题完成]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 甲乙合作修路 5 天。剩下的路段，若甲单干需 4 天，若乙单干需 6 天。问甲单独修这条路共需几天？选项：A. 10  B. 12  C. 15  D. 18"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "剥离剩余工程：剩下的活，甲干要4天，乙干要6天。说明：4 × P甲 = 6 × P乙。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "出效率比：P甲 : P乙 = 6 : 4 = 3 : 2。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "赋效率：直接令 P甲 = 3，P乙 = 2。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求总量 W：看完整过程，比如“合作5天 + 甲单干4天”。W = (3+2)×5 + 3×4 = 25 + 12 = 37。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求目标：甲单独修全长需 T = W ÷ P甲 = 37 ÷ 3 = 12.33 天。（注意解题思路的等效替换最关键）"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "一上来就硬设 W：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "这题没给单独完工的时间，根本没法求公倍数赋 W。这种题的逻辑是反过来的：必须先通过“残局”建立等式算出 P，再去倒推 W。切忌思维定势。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "练就火眼金睛，专门在长篇大论中寻找“描述同一段残余工程的两种不同解法”，这就是方程的等号所在。"}]}]}$$ AS jsonb), NULL, '剩余工程反求的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "剩余工程反求"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_st_remain", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
